import React from 'react';

const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
  },
  heading: {
    fontSize: '2rem',
    marginBottom: '16px',
  },
  paragraph: {
    fontSize: '1rem',
    lineHeight: '1.6',
  }
};

const TermsAndConditions = () => {
  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>Terms and Conditions</h1>
      <p style={styles.paragraph}>
        Welcome to Karpagam Clinic! These terms and conditions outline the rules and regulations for the use of Karpagam Clinic's Website.
      </p>
      <p style={styles.paragraph}>
        By accessing this website we assume you accept these terms and conditions. Do not continue to use Karpagam Clinic if you do not agree to take all of the terms and conditions stated on this page.
      </p>
      {/* Add the rest of your terms and conditions content here */}
    </div>
  );
};

export default TermsAndConditions;
